DO $$ DECLARE function_definition text; BEGIN SELECT pg_get_functiondef(p.oid) INTO function_definition FROM pg_proc AS p JOIN pg_namespace AS n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'nmis_list_enrollee_register' AND pg_get_function_identity_arguments(p.oid) LIKE 'p_search text%, p_sector text%, p_category text%' ORDER BY p.oid DESC LIMIT 1; IF function_definition IS NULL THEN RAISE EXCEPTION 'Required function public.nmis_list_enrollee_register was not found'; END IF; IF function_definition LIKE '%OFFSET p_offset LIMIT p_page_size%' THEN RETURN; END IF; function_definition := replace(function_definition, 'e.id; END;', 'e.id OFFSET p_offset LIMIT p_page_size; END;'); IF function_definition NOT LIKE '%OFFSET p_offset LIMIT p_page_size%' THEN RAISE EXCEPTION 'Could not safely add pagination to public.nmis_list_enrollee_register'; END IF; EXECUTE function_definition; END $$;